export declare const modernEditorialComponentsTheme = "/* \u4EE3\u7801\u5757 */\n#wemd pre {\n  margin: 32px 0;\n  border-top: 5px solid #c76237;\n  border-radius: 1px;\n  background: #23251f;\n  overflow-x: auto;\n  -webkit-overflow-scrolling: touch;\n}\n\n#wemd pre.custom {\n  overflow: hidden;\n  overflow-x: auto;\n}\n\n#wemd pre code,\n#wemd pre code.hljs {\n  display: block;\n  min-width: max-content;\n  padding: 20px 21px;\n  border-radius: 0;\n  color: #e8e6dd;\n  background: #23251f;\n  font-family: \"SFMono-Regular\", Consolas, \"Liberation Mono\", Menlo, monospace;\n  font-size: 13px;\n  line-height: 1.72;\n  white-space: pre;\n}\n\n#wemd pre.custom > .mac-sign {\n  display: block;\n  border-bottom: 1px solid #3d4037;\n  background: #23251f;\n}\n\n#wemd pre code.hljs .hljs-comment,\n#wemd pre code.hljs .hljs-quote {\n  color: #999c90;\n}\n\n#wemd pre code.hljs .hljs-keyword,\n#wemd pre code.hljs .hljs-selector-tag,\n#wemd pre code.hljs .hljs-meta {\n  color: #f09a6d;\n}\n\n#wemd pre code.hljs .hljs-string,\n#wemd pre code.hljs .hljs-doctag,\n#wemd pre code.hljs .hljs-regexp {\n  color: #afc89f;\n}\n\n#wemd pre code.hljs .hljs-number,\n#wemd pre code.hljs .hljs-literal,\n#wemd pre code.hljs .hljs-symbol {\n  color: #dfbe76;\n}\n\n#wemd pre code.hljs .hljs-title,\n#wemd pre code.hljs .hljs-section,\n#wemd pre code.hljs .hljs-type {\n  color: #91bec8;\n}\n\n/* \u6570\u636E\u8868 */\n#wemd .table-container {\n  margin: 34px 0;\n  border-top: 5px solid #c76237;\n  overflow-x: auto;\n  -webkit-overflow-scrolling: touch;\n}\n\n#wemd table {\n  width: 100%;\n  border-collapse: collapse;\n  color: #34362f;\n  background: #f7f6f0;\n  text-align: left;\n}\n\n#wemd table tr {\n  border: none;\n  background: transparent;\n}\n\n#wemd table tr th,\n#wemd table tr td {\n  min-width: 88px;\n  padding: 12px 11px;\n  border: none;\n  border-bottom: 1px solid #d3d3c8;\n  color: #41443a;\n  background: transparent;\n  font-size: 14px;\n  line-height: 1.62;\n  text-align: left;\n}\n\n#wemd table tr th {\n  color: #f2f0e7;\n  background: #34372f;\n  font-weight: 700;\n  letter-spacing: 0.035em;\n}\n\n#wemd table tr:nth-child(2n) {\n  background: #ecebe3;\n}\n\n/* \u7F16\u8F91\u90E8\u63D0\u793A */\n#wemd .callout {\n  margin: 32px 0;\n  padding: 19px 21px;\n  border: 1px solid #cecec3;\n  border-left: 5px solid #626754;\n  border-radius: 1px;\n  color: #41443a;\n  background: #f1f0e9;\n  box-shadow: none;\n}\n\n#wemd .callout-title {\n  display: flex;\n  align-items: center;\n  margin-bottom: 9px;\n  color: #34372f;\n  font-size: 14px;\n  font-weight: 700;\n  letter-spacing: 0.055em;\n}\n\n#wemd .callout-icon {\n  margin-right: 8px;\n  font-size: 15px;\n}\n\n#wemd .callout p {\n  margin: 0;\n  color: #505348;\n  font-size: 15px;\n  line-height: 1.8;\n}\n\n#wemd .callout-warning,\n#wemd .callout-caution {\n  border-left-color: #c76237;\n  background: #f5ebe4;\n}\n\n/* \u53C2\u8003\u8D44\u6599 */\n#wemd .footnote-word,\n#wemd .footnote-ref {\n  color: #9f4828;\n  font-weight: 600;\n}\n\n#wemd .footnotes-sep {\n  margin-top: 52px;\n  padding-top: 20px;\n  border-top: 5px solid #34372f;\n}\n\n#wemd .footnotes-sep:before {\n  display: block;\n  content: \"\u53C2\u8003\u8D44\u6599\";\n  color: #34372f;\n  font-family: \"Songti SC\", \"STSong\", \"Noto Serif CJK SC\", SimSun, serif;\n  font-size: 19px;\n  font-weight: 700;\n  letter-spacing: 0.045em;\n}\n\n#wemd .footnote-item {\n  display: flex;\n  margin-top: 10px;\n}\n\n#wemd .footnote-num {\n  width: 31px;\n  flex-shrink: 0;\n  color: #c76237;\n  font-size: 13px;\n  line-height: 1.75;\n}\n\n#wemd .footnote-item p {\n  width: auto;\n  margin: 0;\n  color: #74776d;\n  font-size: 13px;\n  line-height: 1.75;\n  text-align: left;\n}\n\n/* \u516C\u5F0F\u3001\u56FE\u8868\u548C\u4EFB\u52A1\u5217\u8868 */\n#wemd .block-equation {\n  display: block;\n  margin: 34px 0;\n  padding: 20px 10px;\n  border-top: 1px solid #cecec3;\n  border-bottom: 1px solid #cecec3;\n  text-align: center;\n  overflow-x: auto;\n  -webkit-overflow-scrolling: touch;\n}\n\n#wemd .block-equation > svg {\n  max-width: 300% !important;\n}\n\n#wemd .inline-equation {\n  display: inline;\n}\n\n#wemd .inline-equation > svg {\n  vertical-align: middle;\n}\n\n#wemd pre.mermaid {\n  padding: 22px 12px;\n  border: 1px solid #cecec3;\n  border-top: 5px solid #626754;\n  background: #f7f6f0;\n}\n\n#wemd .task-list-item {\n  display: flex;\n  align-items: flex-start;\n  gap: 0;\n  margin-left: -1.2em;\n  list-style: none;\n}\n\n#wemd .task-list-item input[type='checkbox'] {\n  margin-top: 7px;\n  margin-right: 8px;\n  pointer-events: none;\n}\n";
